function addStep(reason,origin,target,state='proposed',patch=null){fitSteps.push({id:uid(),reason,origin,target,state,patch,basis:clone(byId(target)),time:Date.now()});draft();updateLog();}
function updateLog(){const old=$('#fit-log');if(old)old.remove();if(current())renderFitLog($('#inspector-body'));}
function renderFitLog(pane){if($('#fit-log'))return;const section=el('section',undefined,'section');section.id='fit-log';section.append(el('h3','Fit history'),el('p','Each suggestion is independent. Uncertainty stays local.','hint'));fitSteps.slice(-12).reverse().forEach(step=>{const row=el('div',undefined,'fit-step');row.append(el('p',step.reason),el('span',step.origin+' · '+step.state,'chip '+(step.state==='proposed'?'proposal':step.state==='applied'?'confirmed':'hole')));if(step.state==='proposed'){for(const [name,state]of [['Accept','applied'],['Reject','rejected']]){const button=el('button',name);button.onclick=()=>{if(state==='applied'){const b=byId(step.target);if(!b||JSON.stringify(b)!==JSON.stringify(step.basis)){step.state='stale';status('This item changed. Review a fresh suggestion; current edits are retained.',true);updateLog();return;}snapshot('Before accepting '+step.reason);const changes=clone(step.patch);if(changes.mapping)changes.mapping={...b.mapping,...changes.mapping};Object.assign(b,changes);save(b);render();}step.state=state;draft();inspect();};row.append(button);}}section.append(row);});if(history.length){const range=el('input');range.type='range';range.min='0';range.max=String(history.length);range.value=String(history.length);range.setAttribute('aria-label','Inspect history');const restore=el('button','Restore this point');restore.hidden=true;range.oninput=()=>{const i=+range.value;historyPreview=i===history.length?null:i;const live=blocks;if(historyPreview!==null)blocks=clone(history[i].blocks);render();blocks=live;scene.style.pointerEvents=historyPreview===null?'':'none';restore.hidden=historyPreview===null;status(historyPreview===null?'Current scene':'Preview: '+history[i].reason+' · no state changed');};restore.onclick=()=>{if(historyPreview===null)return;const prior=history[historyPreview];scene.style.pointerEvents='';historyPreview=null;snapshot('Before history restore');restoreScene(prior.blocks);status('Restored '+prior.reason);};section.append(restore);section.append(range);}pane.append(section);}
