function bindSource(target,source){if(target===source){pointing=null;return;}let at=byId(source);const seen=new Set([target]);while(at){if(seen.has(at.id)){status('That would create a source cycle.',true);return;}seen.add(at.id);at=byId(at.sourceId);}const b=byId(target);change(b,'sourceId',source,'Source → '+textOf(byId(source)));pointing=null;render();inspect();}
function position(e){const box=scene.getBoundingClientRect();return{x:(e.clientX-box.left)/zoom,y:(e.clientY-box.top)/zoom};}
function snap(value){return Math.max(0,Math.round(value/16)*16);}
