async function askGrove(prompt,position){if(!prompt.trim())return;if(!ai){status('JEV is off. Your established components still work.');return;}const epoch=++decisionEpoch,basis=JSON.stringify(visible().map(b=>[b.id,b.revision]));decisionTarget=position||null;$('#ask-input').value=prompt;$('#ask-state').textContent='choosing…';const tray=$('#decision-tray');tray.hidden=false;tray.replaceChildren(el('span','Choosing from prepared components and native fields…','pending-choice'));try{await queue;const r=await fetch('/api/decide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,selected})});const result=await r.json();if(!r.ok)throw Error(result.error||'Decision unavailable');if(epoch!==decisionEpoch)return;modelCalls+=result.model_calls;$('#calls').textContent=modelCalls+' model calls';decisionReceipts.push({prompt,...result});lastDecision=result;$('#ask-state').textContent=result.cached?'cached · 0 calls':Math.round(result.total_ms)+' ms';renderDecision(result,epoch);}catch(error){if(epoch!==decisionEpoch)return;$('#ask-state').textContent='needs attention';tray.replaceChildren(el('span',error.message,'chip hole'));}}
function renderDecision(result,epoch){const tray=$('#decision-tray');tray.hidden=false;tray.replaceChildren();const choice=result.choice;const description=el('span',choice.label,'decision-sentence');const accept=el('button',choice.action.op==='question'?'Keep as question':'Apply');accept.onclick=async()=>{if(epoch!==decisionEpoch)return;accept.disabled=true;try{await applyChoice(choice);addStep(choice.label,'jev',selected,'applied');tray.hidden=true;$('#ask-input').value='';}catch(error){accept.disabled=false;status(error.message,true);}};const alternatives=selectField([['','Not that…'],...result.alternatives.filter(o=>o.id!==choice.id).map(o=>[o.id,o.label])],'',id=>{const other=result.alternatives.find(o=>o.id===id);if(other)renderDecision({...result,choice:other},epoch);});alternatives.setAttribute('aria-label','Alternative interpretation');const dismiss=el('button','×');dismiss.setAttribute('aria-label','Dismiss decision');dismiss.onclick=()=>{decisionEpoch++;tray.hidden=true;};tray.append(description,el('span',result.cached?'cached':Math.round(result.elapsed_ms)+' ms · '+result.output_bytes+' B','decision-timing'),accept,alternatives,dismiss);}
async function applyChoice(choice){const a=choice.action;if(a.op==='question'){status('This request needs a capability outside the prepared choices. The prompt remains as a question.',true);return;}if(a.collection){await refreshNative();const n=nativeNode(a.collection);if(!n)throw Error('That native collection no longer exists');if(a.fields&&!a.fields.every(f=>n.properties.some(p=>p.label===f)))throw Error('The collection shape changed. Ask again; your scene is retained.');}if(a.op==='component'){const def=byId(a.definition);if(!def||def.componentDefinition.revision!==a.revision)throw Error('That component revision changed');instantiateComponent(def);return;}if(a.op==='form'){createInputForm(a.collection);return;}if(a.op==='edit_form'){createEditForm(a.sourceId);return;}const b=add(a.part,decisionTarget||undefined);if(a.collection)b.nativeCollection=a.collection;for(const k of ['groupField','field','formula'])if(a[k]!==undefined)b[k]=a[k];if(a.collection)setContent(b,nativeName(a.collection)+(a.part==='chart'?' · '+(a.groupField||a.field):''));if(a.part==='text'){const quoted=$('#ask-input').value.match(/["“](.+?)["”]/);if(quoted)b.notes=quoted[1];}save(b);render();select(b.id);vp.scrollLeft=Math.max(0,(b.rect.x-24)*zoom);vp.scrollTop=Math.max(0,(b.rect.y-24)*zoom);}
function fieldDrop(b,reference,channel){if(reference.collection){const n=nativeNode(reference.collection),p=n?.properties.find(p=>p.label===reference.field&&p.slot===reference.slot);if(!p){status('This exact native field is no longer available.',true);return;}snapshot('Before field drop');b.nativeCollection=reference.collection;b.sourceId=null;if(['board','card','list'].includes(b.part)&&!channel){b.displayFields=[...new Set([...(b.displayFields||[]),reference.field])];}else if(b.part==='chart'&&!channel){b.field=reference.field;b.groupField='';}else{const property=channel||(b.part==='input'?'value':b.part==='shape'?'label':'text');b.properties={...b.properties,[property]:{mode:b.part==='input'?'input':'source',field:reference.field,slot:reference.slot}};b.mapping={...b.mapping,[property]:reference.field};}save(b);render();select(b.id);status('Direct field → '+nativeName(reference.collection)+'.'+reference.field+' · no model');}else if(reference.sourceId){const source=byId(reference.sourceId);if(!source)return;bindSource(b.id,source.id);if(reference.property==='selection'&&b.part==='frame'){b.editSourceId=source.id;save(b);}else if(channel&&['x','y','width','height'].includes(channel)){b.screenBindings={...b.screenBindings,[channel]:reference};save(b);}render();}}
function createEditForm(sourceId){const source=byId(sourceId);if(!source?.nativeCollection){status('This view needs a native collection first.',true);return;}createInputForm(source.nativeCollection);const root=current();root.editSourceId=sourceId;root.sourceId=sourceId;setContent(root,'Edit '+nativeName(source.nativeCollection));for(const input of visible().filter(b=>b.parent===root.id&&b.part==='input')){input.editExisting=true;input.sourceId=sourceId;save(input);}const button=visible().find(b=>b.parent===root.id&&b.part==='button');button.action='update';setContent(button,'Save changes');save(button);save(root);render();}
window.groveDecisions=()=>clone(decisionReceipts);
start();
